{
  "name": "CAN总线BLF日志记录器",
  "name_en": "CAN BLF Log Writer",
  "manufacturer": "",
  "description": "用于将CAN总线消息和错误帧记录为BLF（二进制日志）文件的软件记录器，可生成与Vector工具兼容的日志，常用于车辆网络、嵌入式通信和实验台架中的总线数据采集与离线分析。",
  "description_en": "A software logger that records CAN bus messages and error frames into BLF (Binary Logging File) format, producing logs compatible with Vector tools. It is commonly used for vehicle network testing, embedded communication experiments, and bench-side bus data capture for offline analysis.",
  "actions": [
    {
      "action_name": "auto-on_message_received",
      "description": "将接收到的CAN消息写入BLF日志文件。",
      "description_en": "Write a received CAN message into the BLF log file."
    },
    {
      "action_name": "auto-log_event",
      "description": "向BLF日志添加文本事件标记。",
      "description_en": "Add a text event marker to the BLF log."
    },
    {
      "action_name": "auto-file_size",
      "description": "获取当前日志文件大小估计值。",
      "description_en": "Get the estimated current log file size."
    },
    {
      "action_name": "auto-stop",
      "description": "停止记录并关闭BLF日志文件。",
      "description_en": "Stop logging and close the BLF log file."
    }
  ],
  "tag_hints": [
    "CAN bus logging",
    "BLF file format",
    "vehicle network testing",
    "Vector tools compatibility",
    "bus message recording",
    "offline CAN analysis"
  ]
}

